mapper.select:
SELECT 
  FROM ( 
          WHERE flt10_company_id = #{companyId}
            AND flt10_person_id  = #{personId}
            AND flt10_tr_type    LIKE #{trType}

            AND flt10_account_id = #{accountId}



            AND flt10_reg_date = CAST(#{regDate} AS date)


            AND flt10_reg_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date)


       ) t
 WHERE 1=1

   AND CONCAT(flt10_account_info, flt10_item_nm, flt10_item_cd) ILIKE #{searchText}

 ORDER BY flt10_reg_date, flt10_tr_id

SELECT COALESCE(sys01_flt_only_curr_yn, 'false') = 'true'
  FROM sys01_company
 WHERE sys01_company_id = #{companyId}

mapper.update:
UPDATE flt10_tr
   SET flt10_item_type      = #{req.itemType},
       flt10_item_nm        = #{req.itemName},
       flt10_item_cd        = #{req.itemCode},
       flt10_expect_tr_qty  = #{req.expectTrQty},
       flt10_expect_tr_amt  = #{req.expectTrAmt},
       flt10_tr_reason      = #{req.trReason}
 WHERE flt10_tr_id      = #{req.trId}
   AND flt10_company_id = #{companyId}
   AND flt10_person_id  = #{personId}

mapper.delete:
DELETE FROM flt10_tr
 WHERE flt10_company_id = #{companyId}
   AND flt10_person_id  = #{personId}
   AND flt10_tr_id IN
#{trId}

mapper.update:
UPDATE flt10_tr
   SET flt10_status_cd        = CAST(#{statusCode} AS varchar)
     , flt10_confirmer_id     = #{personId}
     , flt10_confirm_datetime = null
     , flt10_reject_reason    = CASE WHEN CAST(#{statusCode} AS varchar) NOT IN ('20','30') THEN null
                                     ELSE flt10_reject_reason
                                END
 WHERE flt10_tr_id      = #{trId}
   AND flt10_company_id = #{companyId}
   AND flt10_person_id  = #{personId}

